package com.clock.wallpaper;

import android.app.*;import android.content.*;import android.hardware.*;import android.os.*;import android.provider.Settings;import java.util.*;

public class ClockService extends Service implements SensorEventListener {
  static final int INTERVAL=5*60*1000, FLIP_COOLDOWN=8000; SensorManager sm; Sensor accel, prox; boolean near=false, upside=false, faceDown=false, showing=false; long lastWake=0; Handler h=new Handler(Looper.getMainLooper()); PowerManager.WakeLock wakeLock; SharedPreferences sp;
  public static void start(Context c){Intent i=new Intent(c,ClockService.class); if(Build.VERSION.SDK_INT>=26)c.startForegroundService(i);else c.startService(i);}
  BroadcastReceiver doneReceiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){done();}};
  @Override public void onCreate(){super.onCreate();sp=getSharedPreferences("clock",0);registerReceiver(doneReceiver,new IntentFilter("com.clock.wallpaper.WAKE_DONE"));sm=(SensorManager)getSystemService(SENSOR_SERVICE);accel=sm.getDefaultSensor(Sensor.TYPE_ACCELEROMETER);prox=sm.getDefaultSensor(Sensor.TYPE_PROXIMITY);sp.edit().putBoolean("accelerometerAvailable",accel!=null).putBoolean("proximityAvailable",prox!=null).apply();if(accel!=null)sm.registerListener(this,accel,SensorManager.SENSOR_DELAY_NORMAL);if(prox!=null)sm.registerListener(this,prox,SensorManager.SENSOR_DELAY_NORMAL);if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel("clock","Clock",NotificationManager.IMPORTANCE_HIGH);ch.setDescription("Пробуждение часов каждые 5 минут");getSystemService(NotificationManager.class).createNotificationChannel(ch);startForeground(7,new Notification.Builder(this,"clock").setContentTitle("Clock wallpaper active").setSmallIcon(R.drawable.ic_clock).build());}schedule();}
  void schedule(){h.removeCallbacksAndMessages(null);long next=System.currentTimeMillis()+INTERVAL;sp.edit().putLong("nextWake",next).apply();h.postDelayed(()->{wake("timer");schedule();},INTERVAL);}
  void wake(String why){long now=SystemClock.elapsedRealtime();if(!prefs("enabled",true)){note("Отключено в настройках");return;}if(showing){note("Пропуск: заставка уже показывается");return;}if(why.equals("flip")&&now-lastWake<FLIP_COOLDOWN){note("Пропуск: защита от повторного переворота");return;}if((near&&prefs("proximity",true))||(faceDown&&prefs("faceDown",true))){note(near?"Пропуск: датчик приближения":"Пропуск: телефон экраном вниз");return;}showing=true;lastWake=now;sp.edit().putLong("lastWake",System.currentTimeMillis()).putString("lastReason",why).apply();PowerManager pm=(PowerManager)getSystemService(POWER_SERVICE);wakeLock=pm.newWakeLock(PowerManager.SCREEN_BRIGHT_WAKE_LOCK|PowerManager.ACQUIRE_CAUSES_WAKEUP|PowerManager.ON_AFTER_RELEASE,"ClockWallpaper:Wake");wakeLock.acquire(1500);Intent i=new Intent(this,WakeActivity.class).putExtra("reason",why).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);if(Build.VERSION.SDK_INT<23||Settings.canDrawOverlays(this)){startActivity(i);}else{PendingIntent pi=PendingIntent.getActivity(this,42,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder nb=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"clock"):new Notification.Builder(this);nb.setSmallIcon(R.drawable.ic_clock).setContentTitle("Clock").setContentText("Включите показ поверх приложений").setCategory(Notification.CATEGORY_ALARM).setPriority(Notification.PRIORITY_MAX).setAutoCancel(true).setFullScreenIntent(pi,true);getSystemService(NotificationManager.class).notify(42,nb.build());}}
  void note(String s){sp.edit().putString("lastReason",s).putLong("lastEvent",System.currentTimeMillis()).apply();}
  void done(){showing=false;if(wakeLock!=null&&wakeLock.isHeld()){wakeLock.release();wakeLock=null;}sp.edit().putBoolean("showing",false).apply();}
  boolean prefs(String k,boolean d){return sp.getBoolean(k,d);}
  @Override public void onSensorChanged(SensorEvent e){if(e.sensor.getType()==Sensor.TYPE_PROXIMITY){near=e.values[0]<e.sensor.getMaximumRange();sp.edit().putBoolean("near",near).apply();}if(e.sensor.getType()==Sensor.TYPE_ACCELEROMETER){float y=e.values[1],z=e.values[2];boolean was=upside;upside=y<-7.5f;faceDown=z<-7.5f;sp.edit().putBoolean("upside",upside).putBoolean("faceDownState",faceDown).apply();if(!was&&upside&&prefs("flip",true))wake("flip");}}
  @Override public void onAccuracyChanged(Sensor s,int a){}
  @Override public int onStartCommand(Intent i,int f,int id){return START_STICKY;}
  @Override public void onDestroy(){unregisterReceiver(doneReceiver);sm.unregisterListener(this);h.removeCallbacksAndMessages(null);done();super.onDestroy();}
  @Override public android.os.IBinder onBind(Intent i){return null;}
}
